import React from "react";
import { Link } from "react-router-dom";
import Navbar1 from "../../Components/Navbar/Navbar";
import { Container, Row, Col, Card, Button } from "react-bootstrap";
import fi from '../../Images/Components/Fi.png';
import './Contact_us.css';

function Contact_us() {
  return (
    <div>
      <Navbar1 contact={{ borderBottom: '3px solid red' }} />
      <div class='contactus_banner d-flex justify-content-center align-items-center text-center'>
        <br />
        <br />
        <Container>
          <font className='text-warning fs-1'>SER</font><font className='text-white fs-1'>VE</font>
          <br />
          <img src={fi} style={{ width: "150px" }}></img>
          <br />
          <font className='text-white fs-6'><Link to="#" className='text-primary'>Home</Link> /</font>
        </Container>
      </div>
    </div>

  )
}
export default Contact_us;
